    print('npts',len(pts),'heading now',c.heading())
    p=polar(pts)
    print(' '.join('%d:%.2f'%(b,v[1]) for b,v in p.items()))
    print(ascii_map(pts, scale=float(sys.argv[1]) if len(sys.argv)>1 else 0.1))
